-- =====================================================================
-- setup_all.sql — ONE paste for a FRESH Supabase project (amirlwf.ir)
-- Generated by tools/build_setup_all.py — do not edit this file by hand.
--
-- Dashboard -> SQL Editor -> paste ALL of it -> Run.
-- Every part is idempotent: if a statement fails halfway, fix it and run
-- the whole file again (already-applied parts are harmless).
--
-- After this: Authentication -> Users -> create the admin account, then
-- give it the admin flag (see README step 1.4), then fill the three bots
-- in the panel and deploy the Edge Functions.
-- =====================================================================

-- =====================================================================
-- 1/6  schema: tables, RLS, functions, realtime
-- source: supabase/schema.sql
-- =====================================================================
-- ============================================================
-- amirlwf.ir — Supabase schema (run in Dashboard > SQL Editor)
-- Tables: orders, site_content, notifications (+ RLS + Realtime)
-- ============================================================

-- ---------- orders ----------
create table if not exists public.orders (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  name        text not null check (char_length(name) between 2 and 80),
  phone       text check (phone ~ '^09[0-9]{9}$'),
  email       text check (email is null or email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'),
  service     text not null check (service in ('edit', 'web', 'pc')),
  sub_service text,
  description text not null check (char_length(description) between 5 and 2000),
  status      text not null default 'new' check (status in ('new', 'in_progress', 'done')),
  track_token uuid not null,
  source_ip   text,
  source      text not null default 'fa_site' check (source in ('fa_site', 'en_landing')),
  raw_link    text check (raw_link is null or char_length(raw_link) <= 500),
  admin_reply text
);
create index if not exists orders_created_idx on public.orders (created_at desc);
create index if not exists orders_status_idx  on public.orders (status);
create index if not exists orders_ip_idx      on public.orders (source_ip, created_at desc);

-- ---------- site_content (admin-editable key/value JSON) ----------
create table if not exists public.site_content (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);

-- ---------- notifications (one row per dispatched notification) ----------
create table if not exists public.notifications (
  id       bigint generated always as identity primary key,
  order_id bigint references public.orders (id) on delete cascade,
  channel  text not null,               -- site | telegram | whatsapp | rubika
  payload  jsonb,
  sent_at  timestamptz not null default now()
);
create index if not exists notifications_order_idx on public.notifications (order_id);

-- ============================================================
-- Row Level Security
-- ============================================================
alter table public.orders        enable row level security;
alter table public.site_content  enable row level security;
alter table public.notifications enable row level security;

-- helper: is the caller an admin? (role flag in auth user_metadata)
create or replace function public.is_admin()
returns boolean language sql stable as
$$ select coalesce((auth.jwt() -> 'user_metadata' ->> 'role'), '') = 'admin' $$;

-- --- orders ---
-- anon: INSERT only, with server-side CHECKs (phone format enforced by DB too)
-- EN branch: source='en_landing' leads carry a valid email + NULL phone,
-- service edit (free-edit lead) or web (project inquiry); see
-- migration_en_leads.sql + migration_en_web_leads.sql
drop policy if exists orders_anon_insert on public.orders;
create policy orders_anon_insert on public.orders
  for insert to anon
  with check (
    char_length(name) between 2 and 80
    and char_length(description) between 5 and 2000
    and service in ('edit', 'web', 'pc')
    and (
      (source = 'fa_site' and phone ~ '^09[0-9]{9}$')
      or (source = 'en_landing' and service in ('edit', 'web') and phone is null
          and email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')
    )
  );

-- anon: read ONLY their own order, scoped by the unguessable track token
-- (client sends header "x-track-token: <uuid>")
drop policy if exists orders_track_own on public.orders;
create policy orders_track_own on public.orders
  for select to anon
  using (
    track_token::text =
    nullif((current_setting('request.headers', true)::json ->> 'x-track-token'), '')
  );

-- admin (authenticated + role=admin): full access
drop policy if exists orders_admin_all on public.orders;
create policy orders_admin_all on public.orders
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- --- site_content ---
-- anon: read only (pages fetch dynamic overrides; anon can NEVER write)
drop policy if exists site_content_anon_read on public.site_content;
create policy site_content_anon_read on public.site_content
  for select to anon using (true);

-- admin: full access
drop policy if exists site_content_admin_all on public.site_content;
create policy site_content_admin_all on public.site_content
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- --- notifications ---
-- admin: full access (edge functions use service_role and bypass RLS)
drop policy if exists notifications_admin_all on public.notifications;
create policy notifications_admin_all on public.notifications
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- ============================================================
-- Realtime: instant order delivery to admin panel + live tracking
-- (On Supabase Cloud these tables are usually already in the
-- publication; the statements below are idempotent-safe.)
-- ============================================================
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table public.orders;
    exception when duplicate_object then null;
    end;
    begin
      alter publication supabase_realtime add table public.notifications;
    exception when duplicate_object then null;
    end;
    -- portfolio_items is created LATER in this file: guard so a fresh
    -- install does not die with 42P01 (relation does not exist)
    if to_regclass('public.portfolio_items') is not null then
      begin
        alter publication supabase_realtime add table public.portfolio_items;
      exception when duplicate_object then null;
      end;
    end if;
  end if;
end $$;

-- keep updated_at fresh
create or replace function public.touch_updated_at()
returns trigger language plpgsql as
$$ begin new.updated_at = now(); return new; end $$;

drop trigger if exists site_content_touch on public.site_content;
create trigger site_content_touch
  before update on public.site_content
  for each row execute function public.touch_updated_at();

-- ============================================================
-- portfolio showcase: admin-managed work samples (EN + FA pages)
-- public reads visible only; admin full via role flag; uploads go
-- to the public 'portfolio' storage bucket (see migration file)
-- ============================================================
create table if not exists public.portfolio_items (
  id         bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  page       text not null default 'en' check (page in ('en', 'fa')),
  title      text not null check (char_length(title) between 2 and 120),
  caption    text check (caption is null or char_length(caption) <= 500),
  thumb_url  text,
  video_url  text,
  sort       int not null default 0,
  visible    boolean not null default true
);
create index if not exists portfolio_page_idx on public.portfolio_items (page, sort, id);

alter table public.portfolio_items enable row level security;

drop policy if exists portfolio_public_read on public.portfolio_items;
create policy portfolio_public_read on public.portfolio_items
  for select to anon using (visible = true);

drop policy if exists portfolio_admin_all on public.portfolio_items;
create policy portfolio_admin_all on public.portfolio_items
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- portfolio_items -> realtime (table exists now; idempotent)
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table public.portfolio_items;
    exception when duplicate_object then null;
    end;
  end if;
end $$;

-- ============================================================
-- live chat (/callme/): visitor <-> owner via dedicated bot
-- visitor sends via chat-send edge fn; owner replies in Telegram
-- (Reply to the #chat-<visitor> message); delivery is Realtime,
-- DB is history (offline visitors sync missed messages on return)
-- ============================================================
create table if not exists public.chat_messages (
  id         bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  visitor_id text not null check (visitor_id ~ '^[0-9a-f]{8,32}$'),
  sender     text not null check (sender in ('visitor', 'owner')),
  text       text not null check (char_length(text) between 1 and 2000),
  source_ip  text
);
create index if not exists chat_visitor_idx on public.chat_messages (visitor_id, id);

alter table public.chat_messages enable row level security;

-- anon: INSERT visitor messages only (edge fn validates + notifies)
drop policy if exists chat_anon_insert on public.chat_messages;
create policy chat_anon_insert on public.chat_messages
  for insert to anon
  with check (
    sender = 'visitor'
    and visitor_id ~ '^[0-9a-f]{8,32}$'
    and char_length(text) between 1 and 2000
  );

-- anon: read ONLY own thread, scoped by visitor id
-- (client sends header "x-visitor-id: <id>")
drop policy if exists chat_track_own on public.chat_messages;
create policy chat_track_own on public.chat_messages
  for select to anon
  using (
    visitor_id =
    nullif((current_setting('request.headers', true)::json ->> 'x-visitor-id'), '')
  );

-- admin (authenticated + role=admin): full access
drop policy if exists chat_admin_all on public.chat_messages;
create policy chat_admin_all on public.chat_messages
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table public.chat_messages;
    exception when duplicate_object then null;
    end;
  end if;
end $$;

