-- source: supabase/migration_page_content.sql
-- =====================================================================
-- ============================================================
-- amirlwf.ir — migration: per-page content + per-page channels
-- Run AFTER seed.sql on an existing DB (idempotent-safe).
-- New page keys: fa_edit, fa_web, fa_pc (+ richer fa_home/en_home).
-- New: business.page_channels.{en,fa,fa_edit,fa_web,fa_pc} toggles.
-- ============================================================

-- ---------- 1. business.page_channels (inherit legacy toggles) ----------
update public.site_content
set value = value || jsonb_build_object(
  'page_channels',
  jsonb_build_object(
    'en',      coalesce(value->'channels_enabled', '{"phone":false,"email":true,"telegram":true,"whatsapp":true,"rubika":false,"linkedin":true,"youtube":true}'::jsonb),
    'fa',      coalesce(value->'channels_enabled', '{"phone":true,"email":false,"telegram":true,"whatsapp":true,"rubika":true,"linkedin":false,"youtube":false}'::jsonb),
    'fa_edit', coalesce(value->'channels_enabled', '{"phone":true,"email":false,"telegram":true,"whatsapp":true,"rubika":true,"linkedin":false,"youtube":false}'::jsonb),
    'fa_web',  coalesce(value->'channels_enabled', '{"phone":true,"email":false,"telegram":true,"whatsapp":true,"rubika":true,"linkedin":false,"youtube":false}'::jsonb),
    'fa_pc',   coalesce(value->'channels_enabled', '{"phone":true,"email":false,"telegram":true,"whatsapp":true,"rubika":true,"linkedin":false,"youtube":false}'::jsonb)
  )
)
where key = 'business'
  and not (value ? 'page_channels');

